import { it, expect, describe } from "vitest";
import {
  estimateBMR,
  estimateTDEE,
  calculateNutritionTargets,
  macroCalorieCheck,
  missingNutritionFields,
  formatMissingFieldsList,
  lbToKg,
  inToCm,
} from "../nutritionMath.js";

// Nutrition P0, step 2 — "establish a verified numerical baseline" BEFORE touching the meal
// generator. Every expected number below is hand-calculated independently from the formulas
// documented in nutritionMath.js's own comments (Mifflin-St Jeor + the disclosed custom
// occupation/training-frequency TDEE blend), not generated by calling the function and copying
// its output — the one exception is explicitly marked as cross-checked against a live run during
// the Gate A audit, not derived from it.
//
// Reference Case 1 — the Gate A audited example (male, 30, 5'10", 180 lb, light occupation,
// 4x resistance + 2x cardio @ 30min/week, muscle_gain):
//   weightKg = 180 / 2.20462 = 81.646638..., heightCm = 70 * 2.54 = 177.8
//   BMR = 10*81.646638 + 6.25*177.8 - 5*30 + 5 (male offset) = 816.466 + 1111.25 - 150 + 5
//       = 1782.716 -> round -> 1783
//   multiplier = occ(light)=1.35 + resistanceBump(min(4,6)*0.02=0.08)
//              + cardioBump(min(2,6)*0.012 [30min < 45min]=0.024) = 1.454
//   TDEE = round(1783 * 1.454) = round(2592.482) = 2592
//   calories = round(2592 * 1.12 [muscle_gain +12%]) = round(2903.04) = 2903 (floor 1500, not hit)
//   protein = round(180 * 0.85) = 153g -> 612 kcal
//   fat = round(2903 * 0.25 / 9) = round(80.639) = 81g (floor round(180*0.3)=54, not hit) -> 729 kcal
//   carbs = round((2903 - 612 - 729) / 4) = round(1562 / 4) = round(390.5) = 391g (JS rounds .5 up)
const PROFILE_1 = {
  sex: "male",
  age: 30,
  heightIn: 70,
  occupationActivity: "light",
  resistanceFrequency: 4,
  cardioFrequency: 2,
  cardioDurationMin: 30,
  primaryGoal: "muscle_gain",
};
const WEIGHT_1_LB = 180;

// Reference Case 2 — female, 25, 5'5", 140 lb, sedentary occupation, 3x resistance, no cardio,
// fat_loss goal. Deliberately chosen to exercise the FAT FLOOR overriding the calorie-derived
// fat number (a branch Case 1 never touches):
//   weightKg = 140 / 2.20462 = 63.502915..., heightCm = 65 * 2.54 = 165.1
//   BMR = 10*63.502915 + 6.25*165.1 - 5*25 - 161 (female offset) = 635.029 + 1031.875 - 125 - 161
//       = 1380.904 -> round -> 1381
//   multiplier = occ(sedentary)=1.2 + resistanceBump(min(3,6)*0.02=0.06) + cardioBump(0) = 1.26
//   TDEE = round(1381 * 1.26) = round(1740.06) = 1740
//   calories = round(1740 * 0.8 [fat_loss -20%]) = round(1392) = 1392 (floor 1200, not hit)
//   protein = round(140 * 1.0) = 140g -> 560 kcal
//   fat (calorie-derived) = round(1392 * 0.25 / 9) = round(38.667) = 39g
//   fat floor = round(140 * 0.3) = 42g -> 42 > 39, so fat = 42g (FLOOR WINS) -> 378 kcal
//   carbs = round((1392 - 560 - 378) / 4) = round(454 / 4) = round(113.5) = 114g
const PROFILE_2 = {
  sex: "female",
  age: 25,
  heightIn: 65,
  occupationActivity: "sedentary",
  resistanceFrequency: 3,
  cardioFrequency: 0,
  primaryGoal: "fat_loss",
};
const WEIGHT_2_LB = 140;

describe("unit conversions", () => {
  it("lbToKg / inToCm match standard conversion factors", () => {
    expect(lbToKg(180)).toBeCloseTo(81.6466, 3);
    expect(inToCm(70)).toBeCloseTo(177.8, 5);
  });
});

describe("estimateBMR — Mifflin-St Jeor", () => {
  it("Reference Case 1 (male): matches hand-calculated 1783 kcal", () => {
    expect(estimateBMR({ sex: "male", weightKg: lbToKg(180), heightCm: inToCm(70), age: 30 })).toBe(1783);
  });
  it("Reference Case 2 (female): matches hand-calculated 1381 kcal", () => {
    expect(estimateBMR({ sex: "female", weightKg: lbToKg(140), heightCm: inToCm(65), age: 25 })).toBe(1381);
  });
  it("missing sex defaults to the male (+5) offset, not a guess dressed up as the female one", () => {
    const withSex = estimateBMR({ sex: "male", weightKg: lbToKg(180), heightCm: inToCm(70), age: 30 });
    const withoutSex = estimateBMR({ weightKg: lbToKg(180), heightCm: inToCm(70), age: 30 });
    expect(withoutSex).toBe(withSex);
  });
  it("returns null, not NaN or a guess, when any required input is missing", () => {
    expect(estimateBMR({ sex: "male", weightKg: null, heightCm: 177.8, age: 30 })).toBeNull();
    expect(estimateBMR({ sex: "male", weightKg: 81.6, heightCm: null, age: 30 })).toBeNull();
    expect(estimateBMR({ sex: "male", weightKg: 81.6, heightCm: 177.8, age: null })).toBeNull();
    expect(estimateBMR({})).toBeNull();
  });
});

describe("estimateTDEE — BMR-to-TDEE estimation (custom occupation + training-frequency blend, not a single published equation — see nutritionMath.js's own header comment)", () => {
  it("Reference Case 1: matches hand-calculated 2592 kcal", () => {
    expect(estimateTDEE(PROFILE_1, WEIGHT_1_LB)).toBe(2592);
  });
  it("Reference Case 2: matches hand-calculated 1740 kcal", () => {
    expect(estimateTDEE(PROFILE_2, WEIGHT_2_LB)).toBe(1740);
  });
  it("resistance/cardio bumps are capped at 6 sessions/week — more sessions never silently inflate TDEE further", () => {
    const base = estimateTDEE({ ...PROFILE_1, resistanceFrequency: 6, cardioFrequency: 6 }, WEIGHT_1_LB);
    const over = estimateTDEE({ ...PROFILE_1, resistanceFrequency: 20, cardioFrequency: 20 }, WEIGHT_1_LB);
    expect(over).toBe(base);
  });
  it("a longer cardio session (>=45min) uses the higher per-session bump than a shorter one", () => {
    const short = estimateTDEE({ ...PROFILE_1, cardioDurationMin: 30 }, WEIGHT_1_LB);
    const long = estimateTDEE({ ...PROFILE_1, cardioDurationMin: 45 }, WEIGHT_1_LB);
    expect(long).toBeGreaterThan(short);
  });
  it("returns null when BMR can't be computed (incomplete profile), never a guessed TDEE", () => {
    expect(estimateTDEE({ ...PROFILE_1, age: null }, WEIGHT_1_LB)).toBeNull();
  });
});

describe("calculateNutritionTargets — calorie + macro targets", () => {
  it("Reference Case 1: matches hand-calculated 2903/153/391/81", () => {
    const targets = calculateNutritionTargets(PROFILE_1, WEIGHT_1_LB);
    expect(targets).toMatchObject({ estimatedMaintenance: 2592, calories: 2903, protein: 153, carbs: 391, fat: 81 });
  });

  it("Reference Case 2: matches hand-calculated 1392/140/114/42 — including the fat FLOOR overriding the calorie-derived fat number", () => {
    const targets = calculateNutritionTargets(PROFILE_2, WEIGHT_2_LB);
    expect(targets).toMatchObject({ estimatedMaintenance: 1740, calories: 1392, protein: 140, carbs: 114, fat: 42 });
  });

  it("never recommends below the documented safety floor regardless of goal aggressiveness", () => {
    // A very light person on fat_loss should still be floored at 1200 (female) / 1500 (male),
    // not driven arbitrarily low by the -20% adjustment.
    const lightFemale = calculateNutritionTargets({ sex: "female", age: 22, heightIn: 60, occupationActivity: "sedentary", resistanceFrequency: 0, cardioFrequency: 0, primaryGoal: "fat_loss" }, 95);
    expect(lightFemale.calories).toBeGreaterThanOrEqual(1200);
  });

  it("returns null for an incomplete profile rather than a partial/guessed result", () => {
    expect(calculateNutritionTargets({ ...PROFILE_1, heightIn: null }, WEIGHT_1_LB)).toBeNull();
    expect(calculateNutritionTargets(PROFILE_1, null)).toBeNull();
  });

  it("returns null for a zero or negative weight instead of an implausible target", () => {
    expect(calculateNutritionTargets(PROFILE_1, 0)).toBeNull();
  });

  it("records the calculation method used, for transparency/explainability", () => {
    expect(calculateNutritionTargets(PROFILE_1, WEIGHT_1_LB).method).toBe("mifflin_st_jeor");
  });
});

describe("macroCalorieCheck — internal consistency reconciliation", () => {
  it("Reference Case 1's targets reconcile within a few kcal of rounding noise (152*4+391*4+81*9 math)", () => {
    const targets = calculateNutritionTargets(PROFILE_1, WEIGHT_1_LB);
    const check = macroCalorieCheck(targets);
    expect(check.derivedCalories).toBe(targets.protein * 4 + targets.carbs * 4 + targets.fat * 9);
    expect(Math.abs(check.diff)).toBeLessThanOrEqual(5);
  });
  it("returns null for null targets rather than throwing", () => {
    expect(macroCalorieCheck(null)).toBeNull();
  });
});

describe("missingNutritionFields / formatMissingFieldsList", () => {
  it("names exactly what's missing, not a generic message", () => {
    const missing = missingNutritionFields({ age: null, heightIn: 70 }, null);
    expect(missing.map((m) => m.key)).toEqual(["age", "weight"]);
  });
  it("formats 1/2/3+ items in readable English", () => {
    expect(formatMissingFieldsList([{ label: "your age" }])).toBe("your age");
    expect(formatMissingFieldsList([{ label: "your age" }, { label: "your height" }])).toBe("your age and your height");
    expect(formatMissingFieldsList([{ label: "a" }, { label: "b" }, { label: "c" }])).toBe("a, b, and c");
  });
  it("reports nothing missing once every required field is present", () => {
    expect(missingNutritionFields(PROFILE_1, WEIGHT_1_LB)).toEqual([]);
  });
});
